    link({
      op: { type: 'query', id: 1, path: 'whoami', input: undefined, context: {}, signal: null },
      next: () => observable(() => {})
    }).subscribe({
      next: (val) => resolve(val),
      error: (err) => reject(err),
    });
  });

  expect(queryResult).toEqual({ result: { type: 'data', data: 'hello alice' } });

  currentUser = null;
  const errResult = await new Promise((resolve, reject) => {
    link({
